import json

before = json.load(open('baseline-packages.json'))
after = json.load(open('after-cpm-packages.json'))

def to_dict(data):
    result = {}
    for p in data['projects']:
        name = p['path'].split('/')[-1]
        for fw in p['frameworks']:
            for pkg in fw['topLevelPackages']:
                key = (name, fw['framework'], pkg['id'])
                result[key] = pkg['resolvedVersion']
    return result

b = to_dict(before)
a = to_dict(after)

all_keys = sorted(set(b.keys()) | set(a.keys()))

changes = []
unchanged = []
for k in all_keys:
    bv = b.get(k)
    av = a.get(k)
    proj, fw, pkg = k
    if bv != av:
        changes.append((proj, fw, pkg, bv or 'N/A', av or 'N/A'))
    else:
        unchanged.append((proj, fw, pkg, bv))

print("=== CHANGES ===")
if changes:
    for c in changes:
        print(f"  {c[0]} ({c[1]}): {c[2]}  {c[3]} -> {c[4]}")
else:
    print("  None")

print(f"\n=== UNCHANGED: {len(unchanged)} packages ===")
for u in unchanged:
    print(f"  {u[0]} ({u[1]}): {u[2]} {u[3]}")
PYEOF

